bg = test_input[0][0]  # 8

# Find all rectangular regions of zeros
zero_regions = []
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if test_input[r][c] != 0 and test_input[r][c] != bg:
            # Expand this region
            region = set()
            for dr in range(-5, 6):
                for dc in range(-5, 6):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < len(test_input) and 0 <= cc < len(test_input[0]):
                        if 0 <= test_input[rr][cc] <= 9:
                            region.add((rr, cc))

            min_r = min(p[0] for p in region)
            max_r = max(p[0] for p in region)
            min_c = min(p[1] for p in region)
            max_c = max(p[1] for p in region)

            height = max_r - min_r + 1
            width = max_c - min_c + 1

            is_solid = True
            for rr in range(min_r, max_r + 1):
                for cc in range(min_c, max_c + 1):
                    if test_input[rr][cc] == bg or test_input[rr][cc] == 0:
                        is_solid = False
                        break
                if not is_solid:
                    break

            if not is_solid:
                continue

            pat = [[test_input[rr][cc] for cc in range(min_c, max_c + 1)] for rr in range(min_r, max_r + 1)]
            zero_regions.append({
                'type': 'non-zero',
                'top_left': (min_r, min_c),
                'size': (height, width),
                'pattern': pat
            })

print("Non-zero regions found:")
for reg in zero_regions:
    print(f"  {reg['top_left']} {reg['size'][0]}x{reg['size'][1]}")

# Now find the zero regions
zeros_positions = set()
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if test_input[r][c] == 0:
            zeros_positions.add((r,c))

print(f"\nZero positions: {len(zeros_positions)}")

# For each zero position, find bounding box
for z_pos in sorted(zeros_positions):
    min_r, max_r = z_pos[0], z_pos[0]
    min_c, max_c = z_pos[1], z_pos[1]

    for zr in range(max(0, z_pos[0]-5), min(12, z_pos[0]+6)):
        for zc in range(max(0, z_pos[1]-5), min(12, z_pos[1]+6)):
            if test_input[zr][zc] == 0:
                min_r = min(min_r, zr)
                max_r = max(max_r, zr)
                min_c = min(min_c, zc)
                max_c = max(max_c, zc)

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    print(f"\nZero region at ({z_pos[0]}, {z_pos[1]}) size {height}x{width}")

    # Find matching non-zero region with closest top-left
    match = None
    for nz_reg in zero_regions:
        if nz_reg['size'] == (height, width):
            dist = abs(nz_reg['top_left'][0] - z_pos[0]) + abs(nz_reg['top_left'][1] - z_pos[1])
            if match is None or dist < match[2]:
                match = (nz_reg, dist)

    if match:
        nz_reg, dist = match
        rotated = rotate_180(nz_reg['pattern'])
        print(f"  Matched non-zero at {nz_reg['top_left']} with distance {dist}")
        print(f"  Original:\n{nz_reg['pattern']}")
        print(f"  Rotated (to fill):\n{rotated}")
